// The artifacts of the test packs, generated by this SDK, are the ones the Go sdk generates
// (sdk/internal/testdata/golden, written by `go test ./sdk -run Golden`).

import assert from "node:assert/strict";
import { mkdtempSync, readFileSync, readdirSync, rmSync, statSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, relative, sep } from "node:path";
import { fileURLToPath } from "node:url";
import test from "node:test";

import {
  dotted, field, generate, Pack, packFile, packs, pointer, schema, SchemaError,
} from "../src/index.ts";
import type { Meta } from "../src/index.ts";
import { OpenBao } from "./packs/openbao/pack.ts";
import { Tembo } from "./packs/tembo/pack.ts";

const HERE = dirname(fileURLToPath(import.meta.url));
const GOLDEN = join(HERE, "..", "..", "internal", "testdata", "golden");

function tree(d: string): string[] {
  const out: string[] = [];
  const walk = (dir: string) => {
    for (const e of readdirSync(dir, { withFileTypes: true })) {
      const p = join(dir, e.name);
      if (e.isDirectory()) walk(p);
      else if (statSync(p).isFile()) out.push(relative(d, p).split(sep).join("/"));
    }
  };
  walk(d);
  return out.sort();
}

function tmp(): string {
  return mkdtempSync(join(tmpdir(), "packsdk-"));
}

test("the artifacts equal the Go sdk's", () => {
  const out = tmp();
  try {
    generate(out, new OpenBao());
    assert.deepEqual(tree(GOLDEN), tree(out));
    for (const rel of tree(GOLDEN)) {
      const want = readFileSync(join(GOLDEN, rel));
      const got = readFileSync(join(out, rel));
      if (rel.endsWith(".json")) { // the same document; the order of keys is each SDK's
        assert.deepEqual(JSON.parse(got.toString()), JSON.parse(want.toString()), rel);
      } else {
        assert.equal(got.toString(), want.toString(), rel);
      }
    }
  } finally {
    rmSync(out, { recursive: true, force: true });
  }
});

test("a held pack is generated alone too", () => {
  const out = tmp();
  try {
    generate(out, new Tembo());
    assert.deepEqual(["tembo/pack.yaml", "tembo/schema.json", "tembo/templates/tembo.env.ptmpl"], tree(out));
  } finally {
    rmSync(out, { recursive: true, force: true });
  }
});

test("generation is stable", () => {
  const a = tmp();
  const b = tmp();
  try {
    generate(a, new OpenBao());
    generate(b, new OpenBao());
    for (const rel of tree(a)) {
      assert.deepEqual(readFileSync(join(b, rel)), readFileSync(join(a, rel)));
    }
  } finally {
    rmSync(a, { recursive: true, force: true });
    rmSync(b, { recursive: true, force: true });
  }
});

test("pointer and dotted come from the fields", () => {
  const o = new OpenBao();
  assert.equal(pointer(o, (p) => p.bao.storage), "/openbao/storage");
  assert.equal(dotted(o, (p) => p.bao.apiAddr), "openbao.api_addr");
  assert.equal(dotted(o, (p) => p.postgres), "postgres");
  assert.equal(pointer(o, (p) => p.postgres.node.nofailover), "/postgres/node/nofailover");
});

test("a field that is not there is refused", () => {
  assert.throws(() => pointer(new OpenBao(), (p) => p.bao.nope), SchemaError);
  assert.throws(() => pointer(new OpenBao(), (p) => p), SchemaError);
});

test("html is escaped the way encoding/json does", () => {
  class Lt extends Pack {
    f = field("a<b&c>d", { omitempty: true });
    meta(): Meta { return { name: "lt", version: "1" }; }
    packRoot() { return {}; }
  }
  const raw = schema(new Lt()).toString();
  assert.ok(raw.includes("a\\u003cb\\u0026c\\u003ed"));
  assert.equal(JSON.parse(raw).properties.f.default, "a<b&c>d");
});

test("a constraint of another type is refused", () => {
  // a schema no value passes is not written: an enum of another type, a bound of a string, a length of a number
  const cases: [string, () => unknown][] = [
    ["an enum of another type", () => field(0, { enum: ["a"] })],
    ["a bound of a string", () => field("", { minimum: 1 })],
    ["a length of a number", () => field(0, { maxLength: 3 })],
    ["a fractional length", () => field("", { maxLength: 1.5 })],
  ];
  for (const [name, make] of cases) {
    class Bad extends Pack {
      v = make();
      meta(): Meta { return { name: "bad", version: "1" }; }
      packRoot() { return {}; }
    }
    assert.throws(() => schema(new Bad()), SchemaError, name);
  }
});

test("a template that is not in content is refused", () => {
  class Lost extends Pack {
    f = field("", { omitempty: true });
    meta(): Meta { return { name: "lost", version: "1", dir: HERE }; }
    packRoot() { return { content: [{ path: "/etc/x.conf", template: "lost.ptmpl" }] }; }
  }
  assert.throws(() => packFile(new Lost()), /lost\.ptmpl/);
});

test("packs lists what is held once", () => {
  // Tembo does not hold itself; a loop is made by two packs naming each other and is refused by name
  assert.deepEqual(packs(new OpenBao()).map((p) => p.meta().name), ["openbao", "tembo"]);
});
